describe('params (hand-written)', () => {
  const http = () => request(app.getHttpServer())
  const publicRead = (key: string) => http().get(`${URL}/public/${key}`)
  const params = () => app.get(ParamService)
  const builtin = async (key: string) =>
    Number((await ds.query('SELECT id FROM cfg_param WHERE param_key = ?', [key]))[0].id)

  it('only root may write signup switch, role or department defaults, or the WeChat sign-in switch', async () => {
    expect(
      await findId(ds.manager, 'cfg_param', { param_key: 'auth.signup.default_role_code' }),
    ).toBeUndefined()
    for (const key of [
      signupParams.enabled,
      signupParams.defaultRoleId,
      signupParams.defaultDeptId,
      WX_MP_ENABLED_PARAM,
    ]) {
      const id = await builtin(key)
      const [before] = await ds.query<{ param_value: string }[]>(
        'SELECT param_value FROM cfg_param WHERE id = ?',
        [id],
      )
      const denied = await call('editor', 'put', `/${id}`, { paramValue: 'changed' }).expect(403)
      expect(denied.body.code).toBe(Err.IAM_GRANT_EXCEEDS_OWN.code)
      expect((await ds.query('SELECT param_value FROM cfg_param WHERE id = ?', [id]))[0]).toEqual(
        before,
      )
      await ds.query('UPDATE cfg_param SET param_key = ? WHERE id = ?', [`${PREFIX}held_${id}`, id])
      try {
        const created = await call('editor', 'post', '', body(key)).expect(403)
        expect(created.body.code).toBe(Err.IAM_GRANT_EXCEEDS_OWN.code)
        expect(await findId(ds.manager, 'cfg_param', { param_key: key })).toBeUndefined()
      } finally {
        await ds.query('UPDATE cfg_param SET param_key = ? WHERE id = ?', [key, id])
      }
      try {
        const value =
          key === signupParams.enabled || key === WX_MP_ENABLED_PARAM ? 'true' : '999999999'
        await call('admin', 'put', `/${id}`, { paramValue: value }).expect(200)
        expect(
          (await ds.query('SELECT param_value FROM cfg_param WHERE id = ?', [id]))[0].param_value,
        ).toBe(value)
      } finally {
        await call('admin', 'put', `/${id}`, { paramValue: before.param_value }).expect(200)
      }
    }
    const normal = await add(body(unique()))
    await call('editor', 'put', `/${normal.id}`, { paramValue: 'edited' }).expect(200)
    expect((await call('editor', 'get', `/${normal.id}`).expect(200)).body.data.paramValue).toBe(
      'edited',
    )
  })

  it('keys are dotted snake_case and set once, like the secret flag; never builtin through the API', async () => {
    for (const paramKey of ['Upper.case', 'with-dash', '1.digit', 'a b'])
      await create(body(unique(), { paramKey })).expect(400)
    const tag = unique()
    const row = await add(
      body(tag, { isBuiltin: true, nameI18n: { 'en-US': 'English', 'zh-CN': '' } }),
    )
    expect(row).toMatchObject({ isBuiltin: false, nameI18n: { 'en-US': 'English' } })
    await call('admin', 'put', `/${row.id}`, { paramKey: `${tag}.x`, isSecret: true }).expect(200)
    expect((await call('admin', 'get', `/${row.id}`)).body.data).toMatchObject({
      paramKey: tag,
      isSecret: false,
    })
    // an empty value is a value (an empty blacklist)
    await call('admin', 'put', `/${row.id}`, { paramValue: '' }).expect(200)
    expect(await params().get(tag)).toBe('')
  })

  it('builtin params: not deleted (a batch with one deletes nothing), keep isPublic; value and name editable', async () => {
    const id = await builtin(DEFAULT_TIMEZONE_PARAM)
    const mine = await add(body(unique()))
    for (const res of [
      await call('admin', 'delete', `/${id}`),
      await call('admin', 'post', '/batch-delete', { ids: [mine.id, id] }),
      await call('admin', 'put', `/${id}`, { isPublic: false }),
    ]) {
      expect(res.status).toBe(422)
      expect(res.body.code).toBe(Err.SETTINGS_PARAM_BUILTIN.code)
    }
    await call('admin', 'get', `/${mine.id}`).expect(200)
    const stored = (await call('admin', 'get', `/${id}`)).body.data
    await call('admin', 'put', `/${id}`, { paramValue: 'UTC', isPublic: true }).expect(200)
    expect((await publicRead(DEFAULT_TIMEZONE_PARAM).expect(200)).body.data.value).toBe('UTC')
    await call('admin', 'put', `/${id}`, { paramValue: stored.paramValue }).expect(200)
  })

  it('secret values: masked in list, detail, export and the POST answer; the mask PUT back keeps the value', async () => {
    const key = unique()
    const created = await add(body(key, { paramValue: 's3cret-value', isSecret: true }))
    expect(created.paramValue).toBe(PARAM_SECRET_MASK)
    expect((await call('admin', 'get', `/${created.id}`)).body.data.paramValue).toBe(
      PARAM_SECRET_MASK,
    )
    const listed = (await call('admin', 'get').query({ paramKey: key }).expect(200)).body.data
    expect(listed.items.map((p: { paramValue: string }) => p.paramValue)).toEqual([
      PARAM_SECRET_MASK,
    ])
    const xlsx = await call('admin', 'get', '/export')
      .query({ paramKey: key })
      .buffer(true)
      .parse(binary)
      .expect(200)
    expect(cells((await sheet(xlsx.body))!, 2, HEADERS.length)[6]).toBe(PARAM_SECRET_MASK)
    // the edit form sends the loaded row back: the stored value stays; a new value replaces it
    const loaded = (await call('admin', 'get', `/${created.id}`)).body.data
    await call('admin', 'put', `/${created.id}`, { ...loaded, name: 'renamed' }).expect(200)
    expect(await params().get(key)).toBe('s3cret-value')
    await call('admin', 'put', `/${created.id}`, { paramValue: 'next-value' }).expect(200)
    expect(await params().get(key)).toBe('next-value')
    // the builtin secret too
    const initial = await builtin(USER_INITIAL_PASSWORD_PARAM)
    expect((await call('admin', 'get', `/${initial}`)).body.data.paramValue).toBe(PARAM_SECRET_MASK)
  })

  it('a secret value never reaches the action log', async () => {
    const trace = `${PREFIX}${process.pid}-secret-`
    const key = unique()
    const { id } = await add(body(key, { paramValue: 'logged-never-1', isSecret: true }))
    await create(body(unique(), { paramValue: 'logged-never-2', isSecret: true })).set(
      'X-Request-Id',
      `${trace}c`,
    )
    await call('admin', 'put', `/${id}`, { paramValue: 'logged-never-3' }).set(
      'X-Request-Id',
      `${trace}u`,
    )
    for (const suffix of ['c', 'u']) {
      const log = await logOf(ds, `${trace}${suffix}`)
      expect(log).toMatchObject({ domain: 'settings.param', ok: 1 })
      expect(`${log.params} ${log.result}`).not.toMatch(/logged-never/)
    }
  })

  it('public read (no session): public ones only, never a secret one (422 on the pair)', async () => {
    const open = await add(body(unique(), { paramValue: 'open', isPublic: true }))
    const closed = await add(body(unique(), { paramValue: 'closed' }))
    expect((await publicRead(open.paramKey).expect(200)).body.data).toEqual({
      key: open.paramKey,
      value: 'open',
    })
    await publicRead(closed.paramKey).expect(404)
    await publicRead('no.such.key').expect(404)
    const pair = await create(body(unique(), { isSecret: true, isPublic: true }))
    expect(pair.status).toBe(422)
    expect(pair.body.code).toBe(Err.SETTINGS_PARAM_SECRET_PUBLIC.code)
    const secret = await add(body(unique(), { isSecret: true }))
    const res = await call('admin', 'put', `/${secret.id}`, { isPublic: true })
    expect(res.status).toBe(422)
    expect(res.body.code).toBe(Err.SETTINGS_PARAM_SECRET_PUBLIC.code)
    // a secret row flagged public by SQL still is not served
    await ds.query('UPDATE cfg_param SET is_public = 1 WHERE id = ?', [secret.id])
    await params().invalidate(secret.paramKey)
    await publicRead(secret.paramKey).expect(404)
  })

  it('a cache fill racing a write never caches the stale read (read racing a switch to non-public)', async () => {
    const row = await add(body(unique(), { paramValue: 'open', isPublic: true }))
    const key = row.paramKey as string
    // the anonymous read loads the row, then stalls until the admin made the param non-public
    const query = ds.query.bind(ds)
    let loaded!: () => void
    const atGate = new Promise<void>((r) => (loaded = r))
    let release!: () => void
    const gate = new Promise<void>((r) => (release = r))
    let gated = false
    const spy = vi
      .spyOn(ds, 'query')
      .mockImplementation(async (sql: string, args?: Parameters<typeof query>[1]) => {
        const rows = await query(sql, args)
        if (
          !gated &&
          sql.includes('FROM cfg_param WHERE param_key') &&
          Array.isArray(args) &&
          args[0] === key
        ) {
          gated = true
          loaded()
          await gate
        }
        return rows
      })
    try {
      const racing = params().getPublic(key)
      await atGate
      await call('admin', 'put', `/${row.id}`, { isPublic: false }).expect(200)
      release()
      // the version moved during the load: read again (not public), nothing cached
      expect(await racing).toBeNull()
    } finally {
      spy.mockRestore()
    }
    expect(await redis.get(redisKey('param', key))).toBeNull()
    await publicRead(key).expect(404)
    expect(await params().getPublic(key)).toBeNull()
  })

  it('every write drops the cached value; POST /refresh-cache drops all (modify only, action-logged)', async () => {
    const key = unique()
    const row = await add(body(key, { paramValue: 'one' }))
    expect(await params().get(key)).toBe('one')
    await call('admin', 'put', `/${row.id}`, { paramValue: 'two' }).expect(200)
    expect(await params().get(key)).toBe('two')
    // a change behind the API's back stays cached until the refresh
    await ds.query("UPDATE cfg_param SET param_value = 'sql' WHERE id = ?", [row.id])
    expect(await params().get(key)).toBe('two')
    await call('reader', 'post', '/refresh-cache').expect(403)
    const traceId = `${PREFIX}${process.pid}-refresh`
    await call('admin', 'post', '/refresh-cache').set('X-Request-Id', traceId).expect(200)
    expect(await params().get(key)).toBe('sql')
    expect(await logOf(ds, traceId)).toMatchObject({
      domain: 'settings.param',
      verb: 'refresh-cache',
      ok: 1,
    })
    await call('admin', 'delete', `/${row.id}`).expect(200)
    expect(await params().get(key)).toBeNull()
  })
})
